const isDesignPreview=location.protocol==="file:"||new URLSearchParams(location.search).get("preview")==="1";
const $=s=>document.querySelector(s),form=$('#registration-form'),windowButtons=[...document.querySelectorAll('[data-window]')];
const windowNames={'left-front':'Left front','right-front':'Right front','left-rear':'Left rear','right-rear':'Right rear',rear:'Rear windshield'};
const selected=()=>windowButtons.filter(b=>b.getAttribute('aria-pressed')==='true').map(b=>b.dataset.window);
const panelButtons=[...document.querySelectorAll('[data-panel]')];
const panelNames={hood:'Hood','front-bumper':'Front bumper',roof:'Roof',trunk:'Trunk lid','rear-bumper':'Rear bumper','left-front-fender':'Left front fender','right-front-fender':'Right front fender','left-doors':'Left doors','right-doors':'Right doors','left-rear-quarter':'Left rear quarter','right-rear-quarter':'Right rear quarter',mirrors:'Mirrors'};
const productType=()=>form?.elements.type?.value||'tint';
const selectedPanels=()=>panelButtons.filter(b=>b.getAttribute('aria-pressed')==='true').map(b=>b.dataset.panel);
const covered=()=>productType()==='tint'?selected():selectedPanels();
const areaNames=id=>windowNames[id]||panelNames[id]||id;
const menu=$('.menu'),nav=$('#navigation');menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');};nav.querySelectorAll('a').forEach(a=>a.onclick=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');});
const date=new Date();if(form)form.elements.installed.max=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
function refreshSelection(){if(!form)return;const windows=selected();$('#window-count').textContent=`${windows.length} of 5 windows selected`;$('#selected-windows').textContent=windows.length?windows.map(id=>windowNames[id]).join(' · '):'Choose the installed glass above.';$('#window-error').textContent='';windowButtons.forEach(b=>b.querySelector('b').textContent=b.getAttribute('aria-pressed')==='true'?'✓':'+');refreshSms();}
windowButtons.forEach(b=>b.onclick=()=>{b.setAttribute('aria-pressed',String(b.getAttribute('aria-pressed')!=='true'));refreshSelection();});
document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{windowButtons.forEach(w=>w.setAttribute('aria-pressed',String(b.dataset.select==='all'||(b.dataset.select==='sides'&&w.dataset.window!=='rear'))));refreshSelection();});
function refreshSms(){const data=new FormData(form),vehicle=[data.get('make'),data.get('model')].filter(Boolean).join(' ')||'your vehicle';$('#sms-preview').textContent=`To seller ${data.get('sellerName')||'—'} (${data.get('sellerPhone')||'mobile not entered'}): Solarzed ${productType()==='tint'?'window film':'PPF'} registration · ${vehicle} · ${covered().map(areaNames).join(', ')||(productType()==='tint'?'no windows selected':'no panels selected')} · tracking code after registration.`;}
form?.addEventListener('input',refreshSms);
function message(target,text){target.replaceChildren();const p=document.createElement('p');p.className='error-message';p.textContent=text;target.append(p);}
function maskPhone(phone=''){return phone.length>5?phone.slice(0,3)+'••••'+phone.slice(-3):phone;}
function smsStatus(record){if(record.sample)return 'Sample record. No SMS is sent.';const to=record.sellerPhoneMasked||maskPhone(record.sellerPhone);switch(record.sms?.status){case 'submitted':return `Submitted to the SMS service for seller ${to}. Delivery has not been confirmed.`;case 'failed':return `SMS was not accepted by the service for seller ${to}. The installation record is saved.`;case 'unknown':return `SMS outcome is unknown for seller ${to}. Check the SMS service before retrying. The installation record is saved.`;case 'pending':return 'Installation saved. SMS submission is in progress; check this record again shortly.';default:return `SMS not sent. Connect an SMS service to notify the registering seller ${to}.`;}}
function renderRecord(target,record){target.replaceChildren();const card=document.createElement('div');card.className='record';const badge=document.createElement('span');badge.className='badge';badge.textContent=record.sample?'SAMPLE / NO SMS SENT':'INSTALLATION REGISTERED';const h=document.createElement('h3');h.textContent=record.vehicle||`${record.make} ${record.model}`;const code=document.createElement('code');code.textContent=record.code;const dl=document.createElement('dl');for(const [label,value]of [['Product',record.typeLabel||(record.type==='ppf'?'Paint protection film':'Window film')],['VIN',record.vinMasked||(record.vin?record.vin.slice(0,3)+'••••'+record.vin.slice(-6):'—')],['License plate',record.plate],['Model year',record.year||'—'],['Film',record.film],['Serial / batch',record.serial],['Installed on',record.installed],['Shop',record.installer],['Registering seller',record.sellerName],['Invoice',record.invoice],[record.type==='ppf'?'Protected panels':'Tinted windows',((record.type==='ppf'?record.panels:record.windows)||[]).map(areaNames).join(', ')]]){const group=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;group.append(dt,dd);dl.append(group);}const sms=document.createElement('div');sms.className='sms-state';const title=document.createElement('b'),status=document.createElement('span');title.textContent='Seller SMS';status.textContent=smsStatus(record);sms.append(title,status);const note=document.createElement('p');note.className='record-note';note.textContent='Installation registration does not define warranty coverage or duration. Keep the original Solarzed warranty terms and invoice.';const actions=document.createElement('div');actions.className='record-actions';const download=document.createElement('button');download.type='button';download.textContent='Download confirmation';download.onclick=()=>{const safe={...record,areas:((record.type==='ppf'?record.panels:record.windows)||[]).map(areaNames),notice:'Installation record. Warranty terms apply.'};delete safe.phone;delete safe.vin;delete safe.owner;delete safe.sellerPhone;const blob=new Blob([JSON.stringify(safe,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=record.code+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};actions.append(download);card.append(badge,h,code,dl,sms,note,actions);target.append(card);}
const sampleRecord={code:'SZ-DEMO-0001',sample:true,vehicle:'Toyota Camry',year:'2024',plate:'DEMO 123',film:'Solarzed Sample Film',serial:'DEMO-BATCH-01',installed:'2026-01-15',installer:'Example Tint Studio',sellerName:'Example Seller',invoice:'DEMO-001',windows:['left-front','right-front','left-rear','right-rear','rear']};
form?.addEventListener('submit',async e=>{e.preventDefault();const target=$('#registration-result');if(!covered().length){const tint=productType()==='tint';$(tint?'#window-error':'#panel-error').textContent=tint?'Select at least one tinted window, including the rear glass if installed.':'Select at least one protected body panel.';(tint?windowButtons:panelButtons)[0].focus();return;}if(!form.reportValidity())return;const button=$('#register-submit');button.disabled=true;button.textContent='Saving installation…';try{const record=Object.fromEntries(new FormData(form));delete record.windows;if(productType()==='tint')record.windows=selected();else record.panels=selectedPanels();if(isDesignPreview){renderRecord(target,{...record,vehicle:record.make+' '+record.model,code:'SZ-DESIGN-PREVIEW',sample:true,sms:{status:'not_configured'}});return;}const response=await fetch('/api/registrations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(record)});const result=await response.json();if(!response.ok)throw Error(result.error||'Registration could not be completed.');renderRecord(target,result.record);if($('#lookup-code'))$('#lookup-code').value=result.record.code;form.reset();windowButtons.forEach(b=>b.setAttribute('aria-pressed','false'));panelButtons.forEach(b=>b.setAttribute('aria-pressed','false'));applyType();refreshSelection();}catch(error){message(target,error.message==='Failed to fetch'?'The registration server is unavailable. Your installation was not confirmed. Please check the connection.':error.message);}finally{button.disabled=false;button.innerHTML='Register installation <span>↗</span>';}});
$('#lookup-form')?.addEventListener('submit',async e=>{e.preventDefault();const target=$('#lookup-result'),code=$('#lookup-code').value.trim().toUpperCase();if(code===sampleRecord.code){renderRecord(target,sampleRecord);return;}if(isDesignPreview){message(target,'Design preview: choose Try a sample record to see an example confirmation.');return;}try{const response=await fetch('/api/registrations/'+encodeURIComponent(code)),result=await response.json();if(!response.ok)throw Error(result.error||'Record not found.');renderRecord(target,result.record);}catch(error){message(target,error.message==='Failed to fetch'?'The registration server is unavailable.':error.message);}});
if($('#sample'))$('#sample').onclick=()=>{$('#lookup-code').value=sampleRecord.code;renderRecord($('#lookup-result'),sampleRecord);};
if($('#sms-service')&&isDesignPreview)$('#sms-service').textContent='Design preview: no data is saved and no SMS is sent.';
if($('#sms-service')&&!isDesignPreview)fetch('/api/config').then(r=>r.ok?r.json():Promise.reject()).then(c=>{$('#sms-service').textContent=c.smsConfigured?'SMS service connected. Registration will submit a notification to the seller.':'SMS service is not connected. Records can be saved; no SMS will be sent yet.';}).catch(()=>{$('#sms-service').textContent='Registration server unavailable. Start the Solarzed local server to save installations.';});
// Paint protection film: body panel map, presets and product type switch.
const frontPanels=['hood','front-bumper','left-front-fender','right-front-fender','mirrors'];
function refreshPanels(){if(!$('#panel-count'))return;const panels=selectedPanels();$('#panel-count').textContent=`${panels.length} of ${panelButtons.length} panels selected`;$('#selected-panels').textContent=panels.length?panels.map(areaNames).join(' · '):'Choose the protected panels above.';$('#panel-error').textContent='';refreshSms();}
function togglePanel(b){b.setAttribute('aria-pressed',String(b.getAttribute('aria-pressed')!=='true'));refreshPanels();}
panelButtons.forEach(b=>{b.addEventListener('click',()=>togglePanel(b));b.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();togglePanel(b);}});});
document.querySelectorAll('[data-panels]').forEach(b=>b.onclick=()=>{panelButtons.forEach(p=>p.setAttribute('aria-pressed',String(b.dataset.panels==='all'||(b.dataset.panels==='front'&&frontPanels.includes(p.dataset.panel)))));refreshPanels();});
function applyType(){if(!form?.elements.type)return;const tint=productType()==='tint';const glass=$('.window-selector:not(.panel-selector)'),body=$('.panel-selector');if(glass)glass.hidden=!tint;if(body)body.hidden=tint;refreshSms();}
form?.querySelectorAll('input[name=type]').forEach(r=>r.addEventListener('change',applyType));
applyType();refreshSelection();refreshPanels();
